package io.github.polestarcn.companion;
import android.app.Activity;import android.content.*;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.*;
/** Local, bounded photo crop. No storage permission, upload, or third-party crop intent. */
public final class BackgroundCropActivity extends Activity {
 private Bitmap source;private Crop crop;private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean dead;
 private String tr(String a,String b){return AppPreferences.tr(this,a,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setBackgroundColor(PsaDesign.canvas(AppPreferences.dark(this)));Button cancel=new Button(this);cancel.setText(tr("取消","Cancel"));cancel.setOnClickListener(v->{Haptics.tap(this);finish();});page.addView(cancel);HelpDisclosure.add(page,this,tr("裁切说明","Crop help"),tr("拖动图片调整位置，滑块缩放；保存当前日间或夜间背景。图片仅保存在本机。","Drag to position; use the slider to zoom. Saves the current day or night background locally."));crop=new Crop(this);LinearLayout.LayoutParams cropLayout=new LinearLayout.LayoutParams(-1,0,1);cropLayout.gravity=Gravity.CENTER_HORIZONTAL;page.addView(crop,cropLayout);SeekBar zoom=new SeekBar(this);zoom.setMax(200);zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){crop.zoom=1+n/100f;crop.invalidate();}public void onStartTrackingTouch(SeekBar s){Haptics.tap(BackgroundCropActivity.this);}public void onStopTrackingTouch(SeekBar s){}});page.addView(zoom);Button save=new Button(this);save.setText(tr("保存裁切","Save crop"));save.setEnabled(false);page.addView(save);setContentView(page);
 worker.execute(()->{try{BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(getIntent().getData())){BitmapFactory.decodeStream(in,null,options);}int sample=1;while(Math.max(options.outWidth,options.outHeight)/sample>2048)sample*=2;options.inSampleSize=sample;options.inJustDecodeBounds=false;Bitmap decoded;try(InputStream in=getContentResolver().openInputStream(getIntent().getData())){decoded=BitmapFactory.decodeStream(in,null,options);}if(decoded==null)throw new IOException();Bitmap oriented=decoded;try(InputStream exif=getContentResolver().openInputStream(getIntent().getData())){int orientation=new androidx.exifinterface.media.ExifInterface(exif).getAttributeInt(androidx.exifinterface.media.ExifInterface.TAG_ORIENTATION,1);Matrix rotate=new Matrix();if(orientation==3)rotate.postRotate(180);else if(orientation==6)rotate.postRotate(90);else if(orientation==8)rotate.postRotate(270);if(orientation!=1){oriented=Bitmap.createBitmap(decoded,0,0,decoded.getWidth(),decoded.getHeight(),rotate,true);if(oriented!=decoded)decoded.recycle();}}catch(Exception ignored){}final Bitmap image=oriented;runOnUiThread(()->{if(dead){image.recycle();return;}source=image;crop.invalidate();save.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{if(!dead){Toast.makeText(this,tr("无法读取该图片","Cannot read image"),Toast.LENGTH_LONG).show();finish();}});}});
 save.setOnClickListener(v->{if(source==null||crop.getWidth()==0)return;Haptics.tap(this);save.setEnabled(false);Bitmap result=Bitmap.createBitmap(720,Math.max(1,Math.round(720f*getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().widthPixels)),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(result);canvas.scale(result.getWidth()/(float)crop.getWidth(),result.getHeight()/(float)crop.getHeight());crop.paintPhoto(canvas);File target=BackgroundImages.file(this);worker.execute(()->{File tmp=new File(target.getPath()+".tmp");try{try(FileOutputStream out=new FileOutputStream(tmp)){if(!result.compress(Bitmap.CompressFormat.JPEG,95,out))throw new IOException();}if(!tmp.renameTo(target))throw new IOException();AppPreferences.set(this,"background_image_enabled","on");AppPreferences.set(this,"map_backdrop","off");runOnUiThread(()->{if(!dead){setResult(RESULT_OK);finish();}});}catch(Exception e){runOnUiThread(()->{if(!dead){save.setEnabled(true);Toast.makeText(this,tr("保存失败","Save failed"),Toast.LENGTH_LONG).show();}});}finally{result.recycle();tmp.delete();}});});
 }
 private final class Crop extends View {final Paint paint=new Paint(3);float zoom=1,dx,dy,lastX,lastY;Crop(Context c){super(c);setContentDescription(tr("拖动裁切图片","Drag image to crop"));}@Override protected void onMeasure(int ws,int hs){float aspect=getResources().getDisplayMetrics().heightPixels/(float)getResources().getDisplayMetrics().widthPixels;int w=Math.min(MeasureSpec.getSize(ws),Math.round(MeasureSpec.getSize(hs)/aspect));setMeasuredDimension(w,Math.round(w*aspect));}void paintPhoto(Canvas c){if(source==null)return;float scale=Math.max(getWidth()/(float)source.getWidth(),getHeight()/(float)source.getHeight())*zoom;float w=source.getWidth()*scale,h=source.getHeight()*scale;dx=Math.max(-(w-getWidth())/2,Math.min((w-getWidth())/2,dx));dy=Math.max(-(h-getHeight())/2,Math.min((h-getHeight())/2,dy));c.save();c.translate((getWidth()-w)/2+dx,(getHeight()-h)/2+dy);c.scale(scale,scale);c.drawBitmap(source,0,0,paint);c.restore();}@Override protected void onDraw(Canvas c){paintPhoto(c);}@Override public boolean performClick(){return super.performClick();}@Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==0){lastX=e.getX();lastY=e.getY();return true;}if(e.getActionMasked()==2){dx+=e.getX()-lastX;dy+=e.getY()-lastY;lastX=e.getX();lastY=e.getY();invalidate();return true;}if(e.getActionMasked()==1)performClick();return true;}}
 @Override protected void onDestroy(){dead=true;worker.shutdown();super.onDestroy();}
}
